<template>
	<view class="tasks-page">
		<view class="fixed-header tasks-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="nav-side">
					<view class="nav-action" @click="goBack">
						<image class="back-icon" src="/static/fanhui.png" mode="aspectFit" />
					</view>
				</view>
				<view class="nav-title">我的任务</view>
				<view class="nav-side is-right"></view>
			</view>
		</view>

		<scroll-view class="tasks-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerTotalHeight + 'px' }">
			<view class="task-board">
				<view class="task-tabs">
					<view v-for="tab in tabs" :key="tab.value" class="task-tab" :class="{ active: activeTab === tab.value }" @click="activeTab = tab.value">
						<text>{{ tab.label }}</text><view class="tab-underline"></view>
					</view>
				</view>

				<view class="task-summary">
					<text>{{ activeTab === 'daily' ? '今日完成' : '成长进度' }} {{ completedCount }}/{{ visibleTasks.length }}</text>
					<view class="summary-balance"><text>我的钻石</text><image class="diamond-tiny-icon" src="/static/img/zuanshi.png" mode="aspectFit" /><text>{{ balance }}</text></view>
				</view>

				<view class="task-list">
					<view v-for="task in visibleTasks" :key="task.id" class="task-row" :class="{ done: isTaskDone(task) }">
						<view class="task-icon" :class="task.theme">
							<text>{{ getTaskIcon(task.code) }}</text>
						</view>
						<view class="task-main">
							<text class="task-title">{{ task.title }}</text>
							<view class="task-reward"><text>+{{ task.reward }}</text><image class="diamond-tiny-icon" src="/static/img/zuanshi.png" mode="aspectFit" /></view>
						</view>
						<view
							class="task-action"
							:class="{ done: isTaskDone(task) }"
							@click="handleTaskAction(task)"
						>
							<text>{{ isTaskDone(task) ? '已完成' : '去完成' }}</text>
						</view>
					</view>
				</view>
			</view>
		</scroll-view>
	</view>
</template>

<script>
import { fetchMyThoughts } from '../../api/thought';
import { fetchCurrentUser } from '../../api/user';
import { fetchDiamonds } from '../../api/diamond';
import { showRequestError } from '../../utils/feedback';
import { refreshCachedUser } from '../../utils/auth';

export default {
	data() {
		return {
			statusBarHeight: 44,
			headerTotalHeight: 96,
			activeTab: 'daily',
			balance: 0,
			serverTasks: [],
			serverGrowthTasks: [],
			growthTaskDefaults: [
				{ code: 'growth_profile', title: '首次完善个人资料', reward: 30, action: 'profile', theme: 'green' },
				{ code: 'growth_publish', title: '首次发布一条动态', reward: 10, action: 'publish', theme: 'pink' },
				{ code: 'growth_note', title: '首次放飞一张纸条', reward: 10, action: 'note', theme: 'yellow' },
				{ code: 'growth_reply', title: '首次回复一张纸条', reward: 10, action: 'meet', theme: 'blue' }
			],
			user: {},
			records: [],
			tabs: [
				{ label: '每日任务', value: 'daily' },
				{ label: '成长任务', value: 'growth' }
			],
			dailyTasks: [
				{
					id: 'daily_publish',
					title: '发布一条动态',
					desc: '写下一条今天的想法或心情',
					icon: '✎',
					reward: 10,
					target: 1,
					metric: 'todayRecords',
					action: 'publish',
					theme: 'pink'
				},
				{
					id: 'daily_browse',
					title: '逛一逛广场',
					desc: '去广场看看新的同频内容',
					icon: '◎',
					reward: 5,
					target: 1,
					metric: 'visitSquare',
					action: 'square',
					theme: 'blue'
				},
				{
					id: 'daily_profile',
					title: '完善个人介绍',
					desc: '让别人更快了解你',
					icon: '☻',
					reward: 8,
					target: 1,
					metric: 'hasIntro',
					action: 'profile',
					theme: 'green'
				}
			],
			growthTasks: [
				{
					id: 'growth_publish_3',
					title: '累计发布 3 条动态',
					desc: '建立自己的动态树',
					icon: '✦',
					reward: 30,
					target: 3,
					metric: 'totalRecords',
					action: 'publish',
					theme: 'yellow'
				},
				{
					id: 'growth_publish_10',
					title: '累计发布 10 条动态',
					desc: '让主页更有内容',
					icon: '★',
					reward: 80,
					target: 10,
					metric: 'totalRecords',
					action: 'publish',
					theme: 'pink'
				},
				{
					id: 'growth_profile',
					title: '完成基础资料',
					desc: '头像、昵称、性别年龄和城市都补齐',
					icon: '✓',
					reward: 20,
					target: 1,
					metric: 'profileCompleted',
					action: 'profile',
					theme: 'green'
				}
			]
		};
	},
	computed: {
		visibleTasks() {
			return this.activeTab === 'growth' ? this.serverGrowthTasks : this.serverTasks;
		},
		completedCount() {
			return this.visibleTasks.filter((task) => task.completed).length;
		},
		dailyCompletedCount() {
			return this.dailyTasks.filter((task) => this.isTaskDone(task)).length;
		},
		dailyProgress() {
			if (!this.dailyTasks.length) return 0;
			return Math.round((this.dailyCompletedCount / this.dailyTasks.length) * 100);
		},
		todayRecords() {
			const today = new Date();
			return this.records.filter((item) => {
				const date = new Date(item.createdAt || item.openedAt || item.openAt || '');
				return date.getFullYear() === today.getFullYear() &&
					date.getMonth() === today.getMonth() &&
					date.getDate() === today.getDate();
			}).length;
		},
		taskMetrics() {
			return {
				todayRecords: this.todayRecords,
				totalRecords: this.records.length,
				hasIntro: this.user.intro ? 1 : 0,
				profileCompleted: this.user.profileCompleted ? 1 : 0,
				visitSquare: uni.getStorageSync('task_visit_square') ? 1 : 0
			};
		}
	},
	onLoad() {
		this.setHeaderLayout();
		this.markTaskVisit();
		this.loadData();
	},
	onShow() {
		this.loadData();
	},
	methods: {
		setHeaderLayout() {
			try {
				const systemInfo = uni.getSystemInfoSync();
				this.statusBarHeight = systemInfo.statusBarHeight || 44;
				const rpxToPx = (systemInfo.windowWidth || 375) / 750;
				this.headerTotalHeight = this.statusBarHeight + Math.round(92 * rpxToPx);
			} catch (error) {
				this.statusBarHeight = 44;
				this.headerTotalHeight = 96;
			}
		},
		async loadData() {
			try {
				const [user, records, diamonds] = await Promise.all([fetchCurrentUser(), fetchMyThoughts(), fetchDiamonds()]);
				this.user = user || {};
				refreshCachedUser(user);
				this.records = Array.isArray(records) ? records : records.items || [];
				this.balance = Number(diamonds.balance || 0);
				this.serverTasks = (diamonds.tasks || []).map((task, index) => ({
					...task,
					id: task.code,
					theme: ['pink', 'blue', 'green', 'yellow'][index % 4]
				}));
				const growthTasks = Array.isArray(diamonds.growthTasks) && diamonds.growthTasks.length
					? diamonds.growthTasks
					: this.growthTaskDefaults;
				this.serverGrowthTasks = growthTasks.map((task, index) => ({
					...task,
					id: task.code,
					theme: ['green', 'pink', 'yellow', 'blue'][index % 4]
				}));
			} catch (error) {
				showRequestError(error, '加载任务失败');
			}
		},
		markTaskVisit() {
			const todayKey = this.getTodayKey();
			if (uni.getStorageSync('task_visit_day') !== todayKey) {
				uni.removeStorageSync('task_visit_square');
				uni.setStorageSync('task_visit_day', todayKey);
			}
		},
		getTodayKey() {
			const date = new Date();
			return `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`;
		},
		getTaskList(type) {
			return type === 'growth' ? this.growthTasks : this.dailyTasks;
		},
		getCompletedCount(type) {
			return this.getTaskList(type).filter((task) => this.isTaskDone(task)).length;
		},
		getRewardTotal(type) {
			return this.getTaskList(type)
				.filter((task) => this.isTaskDone(task))
				.reduce((total, task) => total + Number(task.reward || 0), 0);
		},
		getTaskValue(task) {
			const value = Number(this.taskMetrics[task.metric] || 0);
			return Math.min(task.target, value);
		},
		getTaskProgress(task) {
			if (!task.target) return 0;
			return Math.min(100, Math.round((this.getTaskValue(task) / task.target) * 100));
		},
		isTaskDone(task) {
			return Boolean(task.completed);
		},
		getTaskIcon(code) {
			return {
				daily_checkin: '✓', daily_browse: '◎', daily_resonance: '♡', daily_publish: '✎', daily_note: '✦', daily_reply: '↩',
				growth_profile: '✓', growth_publish: '✎', growth_note: '✦', growth_reply: '↩'
			}[code] || '◆';
		},
		handleTaskAction(task) {
			if (this.isTaskDone(task)) {
				uni.showToast({ title: '任务已完成', icon: 'none' });
				return;
			}

			if (task.action === 'publish') {
				uni.navigateTo({ url: '/pages/create/index' });
				return;
			}

			if (task.action === 'note') {
				uni.setStorageSync('meetOpenWriteNote', true);
				uni.switchTab({ url: '/pages/meet/index' });
				return;
			}

			if (task.action === 'meet') {
				uni.switchTab({ url: '/pages/meet/index' });
				return;
			}

			if (task.action === 'profile') {
				uni.navigateTo({ url: '/pages/profileComplete/index' });
				return;
			}

			if (task.action === 'square') {
				uni.setStorageSync('task_visit_square', true);
				uni.switchTab({ url: '/pages/square/index' });
			}
		},
		goBack() {
			const pages = getCurrentPages();
			if (pages.length > 1) {
				uni.navigateBack({
					fail: () => {
						uni.switchTab({ url: '/pages/profile/index' });
					}
				});
				return;
			}

			uni.switchTab({ url: '/pages/profile/index' });
		}
	}
};
</script>

<style lang="scss" scoped>
.tasks-page {
	min-height: 100vh;
	background: linear-gradient(180deg, #fff9fc 0%, #f8f8fb 34%, #ffffff 100%);
}

.tasks-header {
	background: rgba(255, 250, 253, 0.96);
	border-bottom: 1rpx solid rgba(241, 232, 240, 0.95);
}

.nav-bar {
	display: flex;
	align-items: center;
	justify-content: space-between;
	min-height: 92rpx;
	padding: 0 22rpx;
}

.nav-side {
	width: 86rpx;
	display: flex;
	align-items: center;
}

.nav-side.is-right {
	justify-content: flex-end;
}

.nav-action {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 58rpx;
	height: 58rpx;
	border-radius: 50%;
	background: #ffffff;
	border: 1rpx solid rgba(222, 213, 230, 0.9);
}

.back-icon {
	width: 34rpx;
	height: 34rpx;
	display: block;
}

.nav-title {
	color: #292832;
	font-size: 30rpx;
	font-weight: 600;
}

.tasks-scroll {
	height: 100vh;
	box-sizing: border-box;
}

.task-board {
	margin: 18rpx 22rpx 0;
	padding: 22rpx 24rpx 18rpx;
	border-radius: 16rpx;
	background: rgba(255, 255, 255, 0.98);
	border: 1rpx solid #f0eaf0;
	box-shadow: 0 8rpx 22rpx rgba(78, 60, 86, 0.04);
}

.task-tabs,
.task-tab,
.task-summary,
.task-row,
.task-action,
.task-icon,
.task-reward {
	display: flex;
	align-items: center;
}

.task-tabs {
	justify-content: center;
	gap: 20rpx;
}

.task-tab {
	flex: 1;
	position: relative;
	flex-direction: column;
	justify-content: center;
	gap: 14rpx;
	height: 82rpx;
	color: #8f89a1;
	font-size: 29rpx;
	font-weight: 500;
}

.task-tab.active {
	color: #292832;
	font-weight: 600;
}

.tab-underline {
	width: 72rpx;
	height: 6rpx;
	border-radius: 999rpx;
	background: transparent;
}

.task-tab.active .tab-underline {
	background: linear-gradient(90deg, #f08bb0, #df77a1);
}

.task-summary {
	justify-content: space-between;
	margin-top: 6rpx;
	padding: 0 2rpx 20rpx;
	color: #aaa3bd;
	font-size: 22rpx;
	font-weight: 400;
}

.task-list {
	display: flex;
	flex-direction: column;
	padding-bottom: calc(20rpx + env(safe-area-inset-bottom));
}

.task-row {
	gap: 20rpx;
	min-height: 136rpx;
	padding: 20rpx 0;
	border-top: 1rpx solid #f2edf5;
	box-sizing: border-box;
}

.task-icon {
	justify-content: center;
	width: 86rpx;
	height: 86rpx;
	border-radius: 14rpx;
	color: #ff7fb1;
	font-size: 34rpx;
	font-weight: 600;
	flex-shrink: 0;
}

.task-icon.pink {
	background: #fff1f7;
}

.task-icon.blue {
	background: #f1f6ff;
	color: #6ea8ff;
}

.task-icon.green {
	background: #effbf5;
	color: #5ed49a;
}

.task-icon.yellow {
	background: #fff8e8;
	color: #ffc44f;
}

.task-main {
	flex: 1;
	min-width: 0;
}

.task-title {
	display: block;
	color: #111111;
	font-size: 29rpx;
	font-weight: 600;
	line-height: 1.25;
}

.task-reward {
	display: flex;
	align-items: center;
	gap: 6rpx;
	margin-top: 14rpx;
	color: #858585;
	font-size: 25rpx;
	line-height: 1.25;
}

.summary-balance {
	display: flex;
	align-items: center;
	gap: 6rpx;
}

.diamond-tiny-icon {
	width: 28rpx;
	height: 28rpx;
	flex-shrink: 0;
}

.task-action {
	justify-content: center;
	width: 150rpx;
	height: 62rpx;
	border-radius: 999rpx;
	background: linear-gradient(135deg, #f18bb0, #e879a2);
	border: 0;
	color: #ffffff;
	font-size: 25rpx;
	font-weight: 500;
	flex-shrink: 0;
	box-shadow: none;
	box-sizing: border-box;
}

.task-action.done {
	background: #f5f0f4;
	color: #aaa3ad;
}
</style>
